/**
 * Embedded base map for the ground-track map and the 3D globe: Natural Earth
 * countries (names, label points, map colours), coastlines and borders,
 * lakes, rivers, US state borders and populated places (public domain),
 * generated by scripts/gen-geodata.mjs. Loaded lazily as its own chunk; no
 * runtime download from any third party.
 *
 * Geometry is on the same spherical Earth (R_EARTH) the simulation uses.
 */
import { R_EARTH } from '../../physics/constants';

export interface WorldData {
  attribution: string;
  precision: number;
  /** Shared country arcs (each border stored once). */
  arcs: string[];
  /** [name, map colour 1-7, label lon*precision, label lat*precision, min label zoom, polygons as arc references (~i = reversed)]. */
  nations: Array<[string, number, number | null, number | null, number, number[][][]]>;
  lakes: Array<[string, string]>;
  states: string[];
  rivers: string[];
  /** Country names referenced by the cities table. */
  countries: string[];
  cities: Array<[string, number, number, number, number, number]>;
}

/** Interleaved [lon, lat, lon, lat, ...] in degrees, with a bounding box. */
export interface Line {
  pts: Float32Array;
  minLon: number;
  maxLon: number;
  minLat: number;
  maxLat: number;
}

export interface Place {
  name: string;
  country: string;
  lon: number;
  lat: number;
  /** Natural Earth scalerank: 0 = most prominent. */
  rank: number;
  popK: number;
}

export interface Country {
  name: string;
  /** Natural Earth MAPCOLOR7 (1-7): neighbouring countries get different values. */
  color: number;
  /** Label anchor (deg). */
  labelLon: number;
  labelLat: number;
  /** Natural Earth min_label: lower values are labelled at smaller scales. */
  minLabel: number;
  /** Polygons: [outer ring, ...holes]. */
  polys: Line[][];
  minLon: number;
  maxLon: number;
  minLat: number;
  maxLat: number;
}

export interface World {
  attribution: string;
  countries: Country[];
  /** Every country polygon ([outer ring, ...holes]): the land. */
  land: Line[][];
  /** Coastlines (arcs used by one country), without the antimeridian and pole cuts. */
  coasts: Line[];
  /** Country-to-country boundaries. */
  borders: Line[];
  lakes: Array<{ name: string; ring: Line }>;
  states: Line[];
  rivers: Line[];
  places: Place[];
}

function lineFrom(pts: ArrayLike<number>): Line {
  let minLon = Infinity, maxLon = -Infinity, minLat = Infinity, maxLat = -Infinity;
  for (let i = 0; i < pts.length; i += 2) {
    const lon = pts[i], lat = pts[i + 1];
    if (lon < minLon) minLon = lon;
    if (lon > maxLon) maxLon = lon;
    if (lat < minLat) minLat = lat;
    if (lat > maxLat) maxLat = lat;
  }
  return { pts: Float32Array.from(pts), minLon, maxLon, minLat, maxLat };
}

export function decodePolyline(s: string, precision: number): Line {
  const out: number[] = [];
  let i = 0, x = 0, y = 0;
  const next = (): number => {
    let shift = 0, result = 0, b: number;
    do {
      b = s.charCodeAt(i++) - 63;
      result |= (b & 0x1f) << shift;
      shift += 5;
    } while (b >= 0x20);
    return result & 1 ? ~(result >> 1) : result >> 1;
  };
  while (i < s.length) {
    x += next();
    y += next();
    out.push(x / precision, y / precision);
  }
  return lineFrom(unwrap(out, false));
}

/**
 * Make longitudes continuous along a line (world-atlas keeps polygons on the
 * sphere, so a ring crossing the antimeridian jumps from +180 to -180).
 * A ring that wraps all the way round (Antarctica) is closed via the pole.
 */
function unwrap(pts: number[], closeRing: boolean): number[] {
  const out = pts.slice();
  let off = 0;
  for (let i = 2; i < out.length; i += 2) {
    const prev = out[i - 2];
    const raw = pts[i] + off;
    // An edge along the pole itself (Antarctica's closing edge) is not a crossing.
    const polar = Math.abs(pts[i + 1]) >= 89.9 && Math.abs(pts[i - 1]) >= 89.9;
    if (!polar && raw - prev > 180) off -= 360;
    else if (!polar && raw - prev < -180) off += 360;
    out[i] = pts[i] + off;
  }
  if (closeRing && out.length >= 4 && Math.abs(out[out.length - 2] - out[0]) > 180) {
    let meanLat = 0;
    for (let i = 1; i < out.length; i += 2) meanLat += out[i];
    const pole = meanLat < 0 ? -90 : 90;
    out.push(out[out.length - 2], pole, out[0], pole);
  }
  return out;
}

/** Polygon edges that only exist because the data is cut at the antimeridian or the pole. */
function isCut(L: Line): boolean {
  return (L.minLon >= 179.9 || L.maxLon <= -179.9) || L.maxLat <= -89.9;
}

export function decodeWorld(d: WorldData): World {
  const p = d.precision;
  const arcs = d.arcs.map((s) => decodePolyline(s, p));
  const ring = (refs: number[]): Line => {
    const out: number[] = [];
    for (const r of refs) {
      const a = arcs[r >= 0 ? r : ~r].pts;
      const n = a.length / 2;
      for (let k = out.length ? 1 : 0; k < n; k++) {
        const j = r >= 0 ? k : n - 1 - k;
        out.push(a[2 * j], a[2 * j + 1]);
      }
    }
    return lineFrom(unwrap(out, true));
  };
  const users = new Int32Array(arcs.length);
  const lastUser = new Int32Array(arcs.length).fill(-1);
  const countries: Country[] = d.nations.map(([name, color, lx, ly, minLabel, polys], ci) => {
    // On the sphere, Antarctica is a pole-only ring with the coast as a hole; on the
    // flat map the coast (closed through the pole by unwrap) is the polygon itself.
    const poleOnly = (r: Line): boolean => r.maxLat <= -89.9 || r.minLat >= 89.9;
    const P = polys.map((poly) => poly.map(ring).filter((r) => !poleOnly(r))).filter((poly) => poly.length > 0);
    for (const poly of polys) {
      for (const r of poly) {
        for (const ref of r) {
          const id = ref >= 0 ? ref : ~ref;
          if (lastUser[id] !== ci) {
            users[id]++;
            lastUser[id] = ci;
          }
        }
      }
    }
    let minLon = Infinity, maxLon = -Infinity, minLat = Infinity, maxLat = -Infinity, big = P[0]?.[0];
    for (const poly of P) {
      const o = poly[0];
      minLon = Math.min(minLon, o.minLon); maxLon = Math.max(maxLon, o.maxLon);
      minLat = Math.min(minLat, o.minLat); maxLat = Math.max(maxLat, o.maxLat);
      if (big && (o.maxLon - o.minLon) * (o.maxLat - o.minLat) > (big.maxLon - big.minLon) * (big.maxLat - big.minLat)) big = o;
    }
    const labelLon = lx !== null ? lx / p : big ? (big.minLon + big.maxLon) / 2 : 0;
    const labelLat = ly !== null ? ly / p : big ? (big.minLat + big.maxLat) / 2 : 0;
    return { name, color, labelLon, labelLat, minLabel, polys: P, minLon, maxLon, minLat, maxLat };
  });
  const borders: Line[] = [];
  const coasts: Line[] = [];
  arcs.forEach((a, i) => {
    if (users[i] >= 2) borders.push(a);
    else if (users[i] === 1 && !isCut(a)) coasts.push(a);
  });
  return {
    attribution: d.attribution,
    countries,
    land: countries.flatMap((c) => c.polys),
    coasts,
    borders,
    lakes: d.lakes.map(([name, r]) => ({ name, ring: decodePolyline(r, p) })),
    states: d.states.map((r) => decodePolyline(r, p)),
    rivers: (d.rivers ?? []).map((r) => decodePolyline(r, p)),
    places: d.cities.map(([name, lon, lat, rank, c, popK]) => ({ name, country: d.countries[c] ?? '', lon: lon / p, lat: lat / p, rank, popK })),
  };
}

let pending: Promise<World> | null = null;
/** Loads and decodes the embedded map once (separate chunk, cached). */
export function loadWorld(): Promise<World> {
  pending ??= import('./world.json').then((m) => decodeWorld((m.default ?? m) as unknown as WorldData));
  return pending;
}

// ------------------------------------------------------------ queries
/** Point-in-ring test; rings may extend past +-180 after unwrapping, so try the equivalent longitudes. */
function inRing(r: Line, lon: number, lat: number): boolean {
  if (lat < r.minLat || lat > r.maxLat) return false;
  for (const L of [lon, lon + 360, lon - 360]) if (L >= r.minLon && L <= r.maxLon && inRingAt(r, L, lat)) return true;
  return false;
}

function inRingAt(r: Line, lon: number, lat: number): boolean {
  const p = r.pts;
  let inside = false;
  for (let i = 0, j = p.length - 2; i < p.length; j = i, i += 2) {
    const xi = p[i], yi = p[i + 1], xj = p[j], yj = p[j + 1];
    if (yi > lat !== yj > lat && lon < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

export type Surface = { kind: 'land'; country: string } | { kind: 'sea' } | { kind: 'lake'; name: string };

function inPolygon(poly: Line[], lon: number, lat: number): boolean {
  if (!inRing(poly[0], lon, lat)) return false;
  for (let k = 1; k < poly.length; k++) if (inRing(poly[k], lon, lat)) return false;
  return true;
}

/** The country at a point, if any. */
export function countryAt(w: World, latDeg: number, lonDeg: number): Country | null {
  const lon = wrapLon(lonDeg);
  for (const c of w.countries) {
    if (latDeg < c.minLat || latDeg > c.maxLat) continue;
    if ((lon < c.minLon || lon > c.maxLon) && (lon + 360 > c.maxLon || lon + 360 < c.minLon) && (lon - 360 < c.minLon || lon - 360 > c.maxLon)) continue;
    for (const poly of c.polys) if (inPolygon(poly, lon, latDeg)) return c;
  }
  return null;
}

/** What is at this point on the embedded map (about 1-2 km accuracy at coastlines). */
export function surfaceAt(w: World, latDeg: number, lonDeg: number): Surface {
  const lon = wrapLon(lonDeg);
  for (const lk of w.lakes) if (inRing(lk.ring, lon, latDeg)) return { kind: 'lake', name: lk.name };
  const c = countryAt(w, latDeg, lon);
  return c ? { kind: 'land', country: c.name } : { kind: 'sea' };
}

export const wrapLon = (lon: number): number => ((((lon + 180) % 360) + 360) % 360) - 180;

const D2R = Math.PI / 180;
/** Great-circle distance (m) and initial bearing (deg from north) from point 1 to point 2. */
export function greatCircle(lat1: number, lon1: number, lat2: number, lon2: number): { distanceM: number; bearingDeg: number } {
  const p1 = lat1 * D2R, p2 = lat2 * D2R, dl = (lon2 - lon1) * D2R;
  const a = Math.sin((p2 - p1) / 2) ** 2 + Math.cos(p1) * Math.cos(p2) * Math.sin(dl / 2) ** 2;
  const distanceM = 2 * R_EARTH * Math.asin(Math.min(1, Math.sqrt(a)));
  const y = Math.sin(dl) * Math.cos(p2);
  const x = Math.cos(p1) * Math.sin(p2) - Math.sin(p1) * Math.cos(p2) * Math.cos(dl);
  return { distanceM, bearingDeg: ((Math.atan2(y, x) / D2R) + 360) % 360 };
}

const POINTS = ['N', 'NNE', 'NE', 'ENE', 'E', 'ESE', 'SE', 'SSE', 'S', 'SSW', 'SW', 'WSW', 'W', 'WNW', 'NW', 'NNW'];
export const compass = (bearingDeg: number): string => POINTS[Math.round((((bearingDeg % 360) + 360) % 360) / 22.5) % 16];

/**
 * A recognisable reference place for a point: the nearest place within
 * 150 km (towns count), otherwise the nearest prominent city.
 * Bearing is from the place to the point ("40 km NE of ...").
 */
export function describeNear(w: World, latDeg: number, lonDeg: number): { place: Place; distanceM: number; bearingDeg: number } | null {
  type Near = { place: Place; distanceM: number; bearingDeg: number };
  let best: Near | null = null;
  let bestMajor: Near | null = null;
  for (const pl of w.places) {
    const g = greatCircle(pl.lat, pl.lon, latDeg, lonDeg);
    const cand = { place: pl, distanceM: g.distanceM, bearingDeg: g.bearingDeg };
    if (!best || g.distanceM < best.distanceM) best = cand;
    if (pl.rank <= 4 && (!bestMajor || g.distanceM < bestMajor.distanceM)) bestMajor = cand;
  }
  if (best && best.distanceM <= 150_000) return best;
  return bestMajor ?? best;
}

/** "40 km NE of Las Cruces" / "at Las Cruces". */
export function nearText(n: { place: Place; distanceM: number; bearingDeg: number } | null): string {
  if (!n) return '';
  if (n.distanceM < 5_000) return `at ${n.place.name}`;
  const km = n.distanceM / 1000;
  return `${km < 100 ? km.toFixed(0) : (Math.round(km / 10) * 10).toFixed(0)} km ${compass(n.bearingDeg)} of ${n.place.name}`;
}
